#!/usr/bin/env python3
"""Ever Forward Unity resolution request + guest-stack argv; no output resize."""
from pathlib import Path
import sys
root=Path(sys.argv[1]); changes={}
def edit(p,old,new):
 s=changes.get(p,(root/p).read_text())
 if s.count(old)!=1: raise SystemExit('resolution request anchor changed: '+p)
 changes[p]=s.replace(old,new,1)
header='#pragma once\n#include <cstddef>\n#include <cstdint>\n#include <cstdlib>\n#include <cstring>\n#include <string>\n#include <string_view>\n#include <vector>\n#include <limits>\n\nnamespace NovaResolution {\nstruct Request { unsigned width=0, height=0; };\ninline Request Parse(const char* value) {\n    if (!value) return {};\n    const std::string_view v(value);\n    if(v=="1080") return {1920,1080};\n    if(v=="720") return {1280,720};\n    if(v=="540") return {960,540};\n    if(v=="360") return {640,360};\n    return {};\n}\ninline Request ForTitle(const char* title, const char* value) {\n    // No generic Switch-style scaler exists. Opt in only to the tested routing\n    // for this Unity title; the engine may ignore these Player arguments.\n    return title && std::string_view(title)=="PPSA04703" ? Parse(value) : Request{};\n}\ninline void Append(std::vector<std::string>& args, Request r) {\n    if(!r.width || !r.height) return;\n    if(args.empty()) args.emplace_back("/app0/eboot.bin");\n    args.emplace_back("-screen-width"); args.push_back(std::to_string(r.width));\n    args.emplace_back("-screen-height"); args.push_back(std::to_string(r.height));\n}\ninline bool StringBytes(const std::vector<std::string>& args, size_t& total) {\n    total=0;\n    if(args.size()>128) return false;\n    for(const auto& arg:args) {\n        if(arg.size()>4095 || arg.find(\'\\0\')!=std::string::npos || total>32768-(arg.size()+1)) return false;\n        total+=arg.size()+1;\n    }\n    return true;\n}\n// The caller reserves StringBytes plus the argv slots in mapped guest stack.\n// Strings cannot remain pointers into the tagged native C++ heap on Android.\ninline bool Copy(const std::vector<std::string>& args, char* storage, size_t capacity, const char** argv) {\n    size_t bytes=0;\n    if(!storage || !argv || !StringBytes(args,bytes) || capacity<bytes) return false;\n    size_t offset=0;\n    for(size_t i=0;i<args.size();++i) {\n        argv[i]=storage+offset;\n        std::memcpy(storage+offset,args[i].c_str(),args[i].size()+1);\n        offset+=args[i].size()+1;\n    }\n    argv[args.size()]=nullptr;\n    return true;\n}\n}\n'
edit('src/common/emulatorConfig.cpp','#include <memory>', '#include <memory>\n#include "common/novaResolutionRequest.h"\n#include <cstdio>')
edit('src/common/emulatorConfig.cpp','\t*g_config = cfg;', '\t*g_config = cfg;\n#if defined(KYTY_NOVA_FEX)\n    const auto request = NovaResolution::ForTitle(std::getenv("NOVA_CACHE_TITLE_ID"),\n                                                 std::getenv("NOVA_UNITY_RESOLUTION"));\n    NovaResolution::Append(g_config->guest_arguments, request);\n    if (request.width) std::fprintf(stderr,\n        "NOVA_RESOLUTION: Unity launch request %ux%u; engine acceptance unverified; host output unchanged\\n",\n        request.width, request.height);\n#endif')
edit('src/loader/runtimeLinker.cpp','#include "common/emulatorConfig.h"', '#include "common/emulatorConfig.h"\n#include "common/novaResolutionRequest.h"')
edit("src/loader/runtimeLinker.cpp",'\t\tconst auto params_size = offsetof(EntryParams, argv) +\n\t\t                         (arguments.size() + 2) * sizeof(const char*);\n\t\tauto* params = reinterpret_cast<EntryParams*>(\n\t\t    (reinterpret_cast<uintptr_t>(main_stack_top) - params_size - 0x100u) &\n\t\t    ~static_cast<uintptr_t>(0x0f));\n\t\tstd::memset(params, 0, params_size);\n\t\tfor (const auto& argument: arguments) {\n\t\t\tparams->argv[params->argc++] = argument.c_str();\n\t\t}','        size_t argument_bytes = 0;\n        EXIT_IF(!NovaResolution::StringBytes(arguments, argument_bytes));\n        const auto params_size = offsetof(EntryParams, argv) +\n                                 (arguments.size() + 2) * sizeof(const char*);\n        auto* params = reinterpret_cast<EntryParams*>(\n            (reinterpret_cast<uintptr_t>(main_stack_top) - params_size - argument_bytes - 0x100u) &\n            ~static_cast<uintptr_t>(0x0f));\n        std::memset(params, 0, params_size + argument_bytes);\n        auto* argument_storage = reinterpret_cast<char*>(params) + params_size;\n        EXIT_IF(!NovaResolution::Copy(arguments, argument_storage, argument_bytes, params->argv));\n        params->argc = static_cast<int>(arguments.size());')
edit("src/graphics/host_gpu/renderer/context.cpp", "#include <cstring>", "#include <cstring>\n#include <chrono>\n#include <cstdio>\n#include \"common/novaResolutionRequest.h\"")
edit("src/graphics/host_gpu/renderer/context.cpp", "\tEndRendering();\n\n\tstd::array<vk::RenderingAttachmentInfo, RENDER_COLOR_ATTACHMENTS_MAX> colors {};", "\tEndRendering();\n"+'#if defined(KYTY_NOVA_FEX)\n    static const bool trace_resolution = [] {\n        const char* trace = std::getenv("NOVA_TRACE_RESOLUTION");\n        return NovaResolution::ForTitle(std::getenv("NOVA_CACHE_TITLE_ID"),\n                                        std::getenv("NOVA_UNITY_RESOLUTION")).width != 0 ||\n               (trace && std::strcmp(trace, "1") == 0);\n    }();\n    if (trace_resolution) {\n        struct Entry { uint32_t w=0,h=0,colors=0,layers=0; uint64_t calls=0; };\n        static thread_local std::array<Entry,32> sizes {};\n        static thread_local auto begin=std::chrono::steady_clock::now();\n        static thread_local uint64_t overflow=0;\n        bool found=false;\n        for(auto& e:sizes) {\n            if(!e.calls || (e.w==state.width && e.h==state.height && e.colors==state.num_color_attachments && e.layers==state.num_layers)) {\n                e.w=state.width; e.h=state.height; e.colors=state.num_color_attachments; e.layers=state.num_layers; ++e.calls; found=true; break;\n            }\n        }\n        if(!found) ++overflow;\n        const auto now=std::chrono::steady_clock::now();\n        if(now-begin>=std::chrono::seconds(5)) {\n            for(auto& e:sizes) if(e.calls) {\n                std::fprintf(stderr,"NOVA_RESOLUTION: actual render area %ux%u colors=%u layers=%u passes=%llu\\n",e.w,e.h,e.colors,e.layers,(unsigned long long)e.calls);\n                e.calls=0;\n            }\n            if(overflow)std::fprintf(stderr,"NOVA_RESOLUTION: additional render dimensions=%llu\\n",(unsigned long long)overflow);\n            overflow=0;begin=now;\n        }\n    }\n#endif\n'+"\n\tstd::array<vk::RenderingAttachmentInfo, RENDER_COLOR_ATTACHMENTS_MAX> colors {};")
for p,s in changes.items(): (root/p).write_text(s)
(root/"src/common/novaResolutionRequest.h").write_text(header)
print("Unity resolution request and bounded actual render-area tracing installed")
